 const [authMode,setAuthMode]=useState("login"),[invite,setInvite]=useState(""),[resetToken,setResetToken]=useState(""),[email,setEmail]=useState("");
 const [advanced,setAdvanced]=useState(""),[preview,setPreview]=useState<{records:number;occurrences:number;reconciliations:number}|null>(null),[csv,setCsv]=useState(""),[mapping,setMapping]=useState<Record<string,string>>({}),[csvRows,setCsvRows]=useState<BudgetRecord[]>([]),[csvWarnings,setCsvWarnings]=useState<string[]>([]);
 const [fundingPayment,setFundingPayment]=useState<NonNullable<typeof payment>|null>(null),[paymentStatus,setPaymentStatus]=useState("");
 const [selectedStart,setSelectedStart]=useState(""),[chooseKind,setChooseKind]=useState(false),[onboarding,setOnboarding]=useState<OnboardingState|null>(null),[planPicker,setPlanPicker]=useState(false),[planIncomeId,setPlanIncomeId]=useState("");
 async function load(){const r=await request("/api/budget");setUser(r.user);setData(r.data);setOnboarding(r.onboarding);return r.data as Data;}
