 const fundingLabel=(start:string)=>new Date(start+"T12:00:00").toLocaleDateString("nb-NO",{month:"long",year:"numeric"})+" · lønning "+new Date(start+"T12:00:00").toLocaleDateString("nb-NO",{day:"numeric",month:"short"});
 function openPayment(p:NonNullable<typeof payment>){setPayment(p);setPaymentStatus(p.status);setError("");}
